'use strict';
// This audit deliberately does NOT prescribe "resistant", "receptive", or
// "changing" participant types. Synthetic responses are generated by a
// condition-blind deterministic process. The same participant/numerosity pair
// receives the same latent response tendency in N, P, and A, so the simulator
// cannot manufacture a persuasive-condition effect.
const reviewParticipants=[
 {id:'sim-1',seed:101,testIndex:0},
 {id:'sim-2',seed:307,testIndex:1},
 {id:'sim-3',seed:911,testIndex:2},
];
const reviewRows=[];let reviewIndex=0,reviewStarted=false,reviewRunning=false,reviewPaused=false,reviewState=null,reviewModel=null,reviewPid=null,reviewPending=null;
const el=id=>document.getElementById(id);
const rounded=n=>Math.max(1,Math.min(400,Math.round(n)));
function hashUnit(text){
 // Small deterministic hash -> [0,1). Reproducible across browsers and runs.
 let h=2166136261;
 for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619);}
 return (h>>>0)/4294967296;
}
function simulatedResponse(participant,trueCount,initial,advice){
 // Match the latent behaviour by participant + numerosity across N/P/A.
 // Most draws lie between own estimate and advice, with occasional movement
 // away or slight overshoot so adaptive grounding routes still get exercised.
 const u=hashUnit(`${participant.seed}|${trueCount}|weight`);
 let weight;
 if(u<0.08) weight=-0.15+u/0.08*0.15;          // -0.15 .. 0.00
 else if(u<0.92) weight=(u-0.08)/0.84;          // 0.00 .. 1.00
 else weight=1+(u-0.92)/0.08*0.15;              // 1.00 .. 1.15
 const trustU=hashUnit(`${participant.seed}|${trueCount}|trust`);
 const trust=1+Math.min(6,Math.floor(trustU*7));
 return {final:rounded(initial+weight*(advice-initial)),trust,weight};
}
async function reviewRequest(path,body,form=false){
 const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'X-CSRF-Token':REVIEW_CONFIG.csrf,...(form?{}:{'Content-Type':'application/json'})}:{},body:body?(form?body:JSON.stringify(body)):undefined});
 if(!response.ok)throw Error(`Request failed (${response.status}). Your completed trials remain saved.`);
 if(form){if(!response.url.endsWith('/instructions'))throw Error('Researcher session expired. Sign in again before starting a new run.');return;}
 const result=await response.json();return result;
}
async function generateReview(){
 if(reviewRunning)return;reviewRunning=true;reviewPaused=false;
 el('review-start').disabled=true;el('review-stop').disabled=false;el('review-model').disabled=true;
 reviewModel=reviewModel||el('review-model').value;
 try{
  while(reviewIndex<reviewParticipants.length&&!reviewPaused){
   const participant=reviewParticipants[reviewIndex];
   if(!reviewStarted){
    const form=new URLSearchParams({csrf_token:REVIEW_CONFIG.csrf,consent:'yes',researcher_test:'1',adviser_mode:'live',model_profile:reviewModel,trials:'12',skip_practice:'1',test_index:String(participant.testIndex),advice_preview_ms:'0',external_id:`SIM_REVIEW_${participant.id}`});
    await reviewRequest('/start',form,true);reviewStarted=true;reviewPid=null;
   }
   if(reviewPending){await reviewRequest('/api/final',reviewPending.payload);reviewRows.push(reviewPending.row);reviewPending=null;el('review-csv').disabled=el('review-json').disabled=false;}
   reviewState=await reviewRequest('/api/state');
   if(reviewState.done){reviewIndex++;reviewStarted=false;continue;}
   const details=reviewState.researcher;
   if(!details||details.mode!=='live')throw Error('A live researcher TEST session is required.');
   if(reviewPid&&details.pid!==reviewPid)throw Error('The active session changed. Do not run other pilots in this browser.');
   reviewPid=details.pid;
   const position=reviewState.trial_in_block;
   const initial=rounded(details.true_count*([.88,1.08,.96,1.12][(details.true_count/8)%4|0]));
   el('review-status').textContent=`${participant.id}: ${details.condition}, trial ${position}. ${reviewRows.length}/108 saved.`;
   // Exercise the same prefetch path as the real task: generate the adviser message BEFORE the current first estimate exists.
   await reviewRequest('/api/prefetch',{trial_token:reviewState.trial_token});
   const advice=await reviewRequest('/api/initial',{trial_token:reviewState.trial_token,estimate:initial,rt_ms:0});
   const response=simulatedResponse(participant,details.true_count,initial,advice.advice_number);
   const ratings={trust:reviewState.ratings_due?response.trust:null,feeling:null};
   reviewPending={payload:{trial_token:reviewState.trial_token,estimate:response.final,rt_ms:0,...ratings,telemetry:{}},row:{simulation_id:participant.id,simulation_seed:participant.seed,adviser_name:reviewState.adviser_name,pid:details.pid,participant_index:details.participant_index,round:reviewState.block,condition:details.condition,trial:position,practice:reviewState.practice,true_count:details.true_count,initial_estimate:initial,advice_number:advice.advice_number,final_estimate:response.final,simulated_weight:response.weight,trust_rating:ratings.trust,advice_text:advice.advice_text,model_profile:reviewModel,...advice.researcher,simulation:true,response_generator:'condition_blind_matched_by_numerosity_v1'}};
   await reviewRequest('/api/final',reviewPending.payload);reviewRows.push(reviewPending.row);reviewPending=null;
   el('review-csv').disabled=el('review-json').disabled=false;
  }
  el('review-status').textContent=reviewIndex===reviewParticipants.length?`Complete: ${reviewRows.length} trials. Download the CSV and full audit.`:`Paused: ${reviewRows.length} trials saved.`;
 }catch(error){reviewPaused=true;el('review-status').textContent=error.message+' Continue retries the current trial.';}
 finally{reviewRunning=false;el('review-stop').disabled=true;el('review-start').textContent='Continue';el('review-start').disabled=reviewIndex===reviewParticipants.length;}
}
function downloadReview(json){
 let content,type,name;
 if(json){content=JSON.stringify({simulation:true,response_generator:'condition_blind_matched_by_numerosity_v1',participants:reviewParticipants,model_profile:reviewModel,complete:reviewIndex===reviewParticipants.length,rows:reviewRows},null,2);type='application/json';name='BEAST-live-review.json';}
 else{
  const fields=['simulation_id','simulation_seed','adviser_name','pid','participant_index','round','condition','trial','practice','true_count','initial_estimate','advice_number','final_estimate','simulated_weight','trust_rating','response_generator','advice_text','word_count','word_count_check','source','live_model','fallback','model_profile','provider','model','reasoning','request_timeout_s','prompt_version','initial_context_available','generation_ms','attempts','validation','grounding_record_check','adaptive_strategy','adaptive_summary','adaptive_summary_in_prompt','first_draft','displayed_draft','length_retry_used','length_retry_success','review_reasons','attempt_log'];
  const cell=value=>{let s=value==null?'':typeof value==='object'?JSON.stringify(value):String(value);if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};
  content='\uFEFF'+[fields,...reviewRows.map(r=>fields.map(k=>r[k]))].map(row=>row.map(cell).join(',')).join('\r\n');type='text/csv;charset=utf-8';name='BEAST-live-review.csv';
 }
 const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
el('review-start').onclick=generateReview;el('review-stop').onclick=()=>{reviewPaused=true;el('review-stop').disabled=true;};el('review-csv').onclick=()=>downloadReview(false);el('review-json').onclick=()=>downloadReview(true);
